# Stop hook: append rtk session stats to ~/.claude/reports/token-usage.md.
# Idempotent per-day heading. One row per session.

$ErrorActionPreference = 'SilentlyContinue'

$ClaudeRoot = if ($env:CLAUDE_CONFIG_DIR) { $env:CLAUDE_CONFIG_DIR } else { Join-Path $env:USERPROFILE '.claude' }
$reportsDir = Join-Path $ClaudeRoot 'reports'
$file       = Join-Path $reportsDir 'token-usage.md'
if (-not (Test-Path $reportsDir)) { New-Item -ItemType Directory -Force -Path $reportsDir | Out-Null }

# Pull rtk gain session JSON (best-effort; rtk may be missing or schema may differ)
$json = $null
try {
    $raw = & rtk gain --session --json 2>$null
    if ($raw) { $json = ($raw -join "`n") | ConvertFrom-Json }
} catch {}

$today     = Get-Date -Format 'yyyy-MM-dd'
$timestamp = Get-Date -Format 'HH:mm'

$saved = 'n/a'
$ratio = 'n/a'
$count = 'n/a'
if ($json) {
    $sess = $null
    if     ($json.session)  { $sess = $json.session }
    elseif ($json.PSObject.Properties['session_total']) { $sess = $json.session_total }
    else { $sess = $json }
    if ($sess.total_saved)  { $saved = $sess.total_saved }
    if ($sess.savings_ratio) { $ratio = "{0:N1}%" -f ([double]$sess.savings_ratio * 100) }
    if ($sess.commands)     { $count = $sess.commands }
}

$row = "| $timestamp | $count | $saved | $ratio |"

if (-not (Test-Path $file)) {
    $header = @(
        '# Token Usage Report',
        '',
        '_Auto-generated by Stop hook (`token-report.ps1`). Append-only. One row per session._',
        ''
    ) -join "`n"
    Set-Content -Path $file -Value $header -Encoding UTF8
}

$content = Get-Content $file -Raw -Encoding UTF8
$dayHeader = "## $today"
if (-not $content -or ($content -notmatch [regex]::Escape($dayHeader))) {
    $tableHeader = "`n$dayHeader`n`n| Time | Commands | Tokens saved (rtk) | Saved ratio |`n|---|---|---|---|"
    Add-Content -Path $file -Value $tableHeader -Encoding UTF8
}
Add-Content -Path $file -Value $row -Encoding UTF8

exit 0

input.content:
# RTK Optimal Architecture — Auto-Rewrite on Windows Native

## Context

RTK's own `rtk init -g` hook requires Bash and does not work on Windows native.
Current enforcement is discipline-based (text rules only) — 222 `rtk read` violations in session history
confirm discipline alone is insufficient. User goal: "rtk로 모든 명령어 최적화" (all command optimization).

**Key insight**: RTK's shell hook can't run on Windows native, but Claude Code's PreToolUse hook system
(Node.js, platform-independent) can intercept every Bash tool call and rewrite commands before they
execute. This bypasses RTK's Windows limitation entirely.

**FOMO gate**: "deterministic enforcement, currently failing without it?" — YES. Documented violations
(222 instances) + user's explicit stated goal. Passes.

---

## Architecture (4 Layers)

```
┌─────────────────────────────────────────────────────────────────┐
│  LAYER 1 (NEW): PreToolUse Auto-Rewrite                         │
│  hooks/rtk-prerewrite.js                                        │
│  "git status"       → "rtk git status"                          │
│  "git add && tsc"   → "rtk git add && rtk tsc"                  │
│  "echo hello"       → (passthrough)                             │
│  "rtk tsc"          → (passthrough, already prefixed)           │
│  Result: 100% coverage, no discipline required                  │
└─────────────────────────────────────────────────────────────────┘
           ↓ passes rewritten command
┌─────────────────────────────────────────────────────────────────┐
│  LAYER 2 (REFACTORED): Documentation SOT                        │
│  RTK.md       — Tool Selection Matrix + fix L33 + hook status   │
│  feedback_rtk.md  — pure pointer (3 lines, no own rules)        │
│  AGENTS.md    — Self-Check §1 simplified                        │
│  CLAUDE.md    — flip "not supported" → "active via hook"        │
└─────────────────────────────────────────────────────────────────┘
           ↓
┌─────────────────────────────────────────────────────────────────┐
│  LAYER 3 (ENHANCED): Feedback Loop                              │
│  token-report.ps1 — append `rtk discover` output after         │
│  gain stats; serves as ongoing hook-compliance audit            │
└─────────────────────────────────────────────────────────────────┘
           ↓
┌─────────────────────────────────────────────────────────────────┐
│  LAYER 4 (UNCHANGED): Existing Enforcement                      │
│  PostToolUse file-type hook (tsc/vitest/php-lint)               │
│  .rtk/filters.toml (docker/php output filters)                  │
│  rtk gain (session stats)                                       │
└─────────────────────────────────────────────────────────────────┘
```

---

## Step 1 — Create `hooks/rtk-prerewrite.js`

**File**: `%USERPROFILE%\.claude\hooks\rtk-prerewrite.js` (NEW)

```javascript
'use strict';

const EXEMPT = new Set([
  'echo', 'printf', 'pwd', 'whoami', 'cd', 'pushd', 'popd',
  'source', '.', 'export', 'unset', 'set', 'env',
  'true', 'false', 'exit', 'return', 'break', 'continue',
  '[', 'test', 'if', 'while', 'for', 'do', 'done', 'fi',
  'then', 'else', 'elif', 'case', 'esac', 'function',
  'read', 'wait', 'sleep', 'kill', 'exec', 'eval',
  'mkdir', 'rmdir', 'rm', 'mv', 'cp', 'touch', 'chmod', 'chown',
  'type', 'which', 'where',
]);

function processSegment(seg) {
  const trimmed = seg.trim();
  if (!trimmed) return seg;
  if (trimmed.startsWith('RTK_DISABLED=1')) return seg;

  let prefix = '';
  let rest = trimmed;
  const assignMatch = rest.match(/^([A-Z_][A-Z0-9_]*=[^\s]*\s+)*/i);
  if (assignMatch && assignMatch[0]) {
    prefix = assignMatch[0];
    rest = rest.slice(prefix.length).trim();
    if (!rest) return seg;
  }

  if (rest.startsWith('rtk ') || rest === 'rtk') return seg;

  const cmdWord = rest.split(/\s+/)[0].replace(/^[!-]+/, '');
  if (EXEMPT.has(cmdWord)) return seg;
  if ('({)}' .includes(cmdWord)) return seg;

  const leading  = seg.match(/^\s*/)[0];
  const trailing = seg.match(/\s*$/)[0];
  return leading + prefix + 'rtk ' + rest + trailing;
}

function splitByLogicalOps(cmd) {
  const tokens = [];
  let cur = '';
  let i = 0;
  while (i < cmd.length) {
    const ch = cmd[i];
    if (ch === "'") {
      let j = i + 1; while (j < cmd.length && cmd[j] !== "'") j++;
      cur += cmd.slice(i, j + 1); i = j + 1; continue;
    }
    if (ch === '"') {
      let j = i + 1;
      while (j < cmd.length && cmd[j] !== '"') { if (cmd[j] === '\\') j++; j++; }
      cur += cmd.slice(i, j + 1); i = j + 1; continue;
    }
    if (ch === '`') {
      let j = i + 1; while (j < cmd.length && cmd[j] !== '`') j++;
      cur += cmd.slice(i, j + 1); i = j + 1; continue;
    }
    if (ch === '$' && cmd[i + 1] === '(') {
      let depth = 0, j = i;
      while (j < cmd.length) {
        if (cmd[j] === '(') depth++;
        else if (cmd[j] === ')') { depth--; if (depth === 0) { j++; break; } }
        j++;
      }
      cur += cmd.slice(i, j); i = j; continue;
    }
    if (ch === '&' && cmd[i + 1] === '&') { tokens.push({ text: cur, sep: '&&' }); cur = ''; i += 2; continue; }
    if (ch === '|' && cmd[i + 1] === '|') { tokens.push({ text: cur, sep: '||' }); cur = ''; i += 2; continue; }
    if (ch === '|')  { cur += ch; i++; continue; }   // pipe: do NOT split
    if (ch === ';')  { tokens.push({ text: cur, sep: ';' }); cur = ''; i++; continue; }
    cur += ch; i++;
  }
  tokens.push({ text: cur, sep: '' });
  return tokens;
}

function rewriteCommand(cmd) {
  const tokens = splitByLogicalOps(cmd);
  let changed = false;
  const rewritten = tokens.map(({ text, sep }) => {
    const newText = processSegment(text);
    if (newText !== text) changed = true;
    return { text: newText, sep };
  });
  if (!changed) return null;
  return rewritten.map(({ text, sep }) => text + sep).join('');
}

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => { input += chunk; });
process.stdin.on('end', () => {
  try {
    const payload = JSON.parse(input);
    if (payload.tool_name !== 'Bash') process.exit(0);
    const originalCommand = (payload.tool_input && payload.tool_input.command) || '';
    if (!originalCommand) process.exit(0);
    const rewritten = rewriteCommand(originalCommand);
    if (rewritten === null) process.exit(0);
    process.stdout.write(JSON.stringify({ modified_input: { command: rewritten } }));
    process.exit(0);
  } catch (_) {
    process.exit(0);  // fail-safe: passthrough on any error
  }
});
```

**Failure modes**: If Node not in PATH / file missing → hook errors → Claude Code passes original command
through unchanged. RTK text rules remain as backstop. No regression from current state.

---

## Step 2 — Add PreToolUse Hook to `settings.json`

**File**: `%USERPROFILE%\.claude\settings.json`

Insert before `"SessionStart"` inside the `"hooks"` object:

```json
"PreToolUse": [
  {
    "matcher": "Bash",
    "hooks": [
      {
        "type": "command",
        "command": "node \"%USERPROFILE%/.claude/hooks/rtk-prerewrite.js\"",
        "async": false
      }
    ]
  }
],
```

`async: false` is mandatory — PreToolUse must complete before the command executes.

---

## Step 3 — Append `rtk discover` to `token-report.ps1`

**File**: `%USERPROFILE%\.claude\hooks\token-report.ps1`

Replace `exit 0` on the final line (line 54) with:

```powershell
# rtk discover: missed savings audit — compliance check for PreToolUse hook coverage.
try {
    $discoverRaw = & rtk discover --all 2>$null
    if ($discoverRaw) {
        $block = @('', '### rtk discover (missed savings)', '```',
                   ($discoverRaw -join "`n"), '```', '') -join "`n"
        Add-Content -Path $file -Value $block -Encoding UTF8
    }
} catch {}

exit 0
```

After the PreToolUse hook is active, `rtk discover` output should shrink toward zero each session.
If it doesn't, it pinpoints exactly which command patterns the hook is missing.

---

## Step 4 — Fix `RTK.md`

**File**: `%USERPROFILE%\.claude\RTK.md`

**Change A** — Add Tool Selection Matrix immediately after the `# RTK` title line:

```markdown
## Tool Selection Matrix

